"""Idempotent balance values. Native impact arithmetic and data farming share a route."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]

def generate():
    rules=json.loads((ROOT/'rules/balance-creative.json').read_text())
    (ROOT/'native/tfm2_custom_ai/src/balance_data.rs').write_text(
        '// Generated by tools/generate-balance-creative.py.\n'+
        ''.join(f'pub const {k.upper()}: usize = {v};\n' for k,v in rules.items()),encoding='utf-8')
    path=ROOT/'Claude outputs/unified_theory/rework.json'
    data=json.loads(path.read_text());data['constants']['FR_DAMAGE_PERCENT']=rules['frieren_damage_percent']
    path.write_text(json.dumps(data,indent=2)+'\n',encoding='utf-8')
    for path in (ROOT/'mods').glob('*/champion/*.data_champion'):
        data=json.loads(path.read_text());ident=data['id']
        if ident=='tfm2_custom_coder':
            data['stat']['hp']=rules['coder_hp'];data['growth']['hp']=rules['coder_hp_growth']
            data.setdefault('passive',{}).setdefault('params',{})['balance_creative_v1']=1
        elif ident=='tfm2_frieren_frieren':
            for effect in data['attack']['effect']['applied_effects']:
                if effect['effect'].get('type')=='ApAttack':
                    effect['effect']={'type':'Native','effect_ref':'tfm2_custom_ai:frieren_basic_damage'}
        elif ident=='tfm2_jojo_dio':
            def knives(node):
                if isinstance(node,dict):
                    if node.get('type')=='TargetProjectile' and node.get('name','').endswith('_knife'):
                        node['applied_effects']=[{'effect':{'type':'Native','effect_ref':'tfm2_custom_ai:dio_farm_knife'},'casting_type':'Targeting'}]
                    else:
                        for value in node.values():knives(value)
                elif isinstance(node,list):
                    for value in node:knives(value)
            knives(data['skill'])
        else:continue
        path.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')

if __name__=='__main__':generate()
